`timescale 1ns/1ps
module tb_hbm_int8_line #(parameter integer PIPE = 0);
 reg clk=0; always #5 clk=~clk;
 reg rst_n=0, int8_mode=1, s_valid=0, m_ready=0;
 reg [1087:0] s_data=0;
 wire s_ready,m_valid; wire [1087:0] m_data;
 ot_hbm_accel_int8_line #(.PIPE(PIPE)) dut(.*);
 reg [1087:0] expect_q [0:2047];
 integer wr=0,rd=0,cycle=0,accepted=0,first_accept=-1,first_emit=-1;
 integer lane,n,ix,ival; reg [31:0] fbits; shortreal unused_value;
 reg [1087:0] lo,hi,old_data; reg old_stall=0;
 // Reference is IEEE FP32 representation of signed integers, generated by
 // Python struct.pack. No shared normalisation implementation with the DUT.
 reg [15:0] golden [0:255];
 initial $readmemh("golden.hex",golden);
 always @(posedge clk) begin
  if (!rst_n) begin wr=0;rd=0;old_stall=0;end
  else begin
   if(old_stall && (!m_valid || m_data !== old_data)) $fatal(1,"stalled output changed");
   if(m_valid && m_ready) begin
    if(first_emit<0) first_emit=cycle;
    if(rd==wr || m_data !== expect_q[rd]) $fatal(1,"beat mismatch at %0d cycle %0d",rd,cycle);
    rd=rd+1;
   end
   if(s_valid && s_ready) begin
    if(first_accept<0) first_accept=cycle;
    accepted=accepted+1;
    if(int8_mode) begin
     lo=0;hi=0;
     for(lane=0;lane<64;lane=lane+1) begin
      lo[16*lane+:16]=golden[s_data[8*lane+:8]];
      hi[16*lane+:16]=golden[s_data[512+8*lane+:8]];
     end
     expect_q[wr]=lo; expect_q[wr+1]=hi; wr=wr+2;
    end else begin expect_q[wr]=s_data;wr=wr+1;end
   end
   old_stall=m_valid && !m_ready;old_data=m_data;
  end
  cycle=cycle+1;
 end
 task send(input integer base,input integer mode);
 begin
  @(negedge clk); int8_mode=mode; s_valid=1;
  for(ix=0;ix<136;ix=ix+1) s_data[ix*8+:8]=(base+ix)%256;
  while(!s_ready) @(negedge clk);
  @(negedge clk);s_valid=0;
 end endtask
 initial begin
  repeat(3) @(negedge clk);rst_n=1;m_ready=1;
  // Exhaust every signed code across both low and high halves.
  send(0,1);send(128,1);
  for(n=0;n<120;n=n+1) send(n*37,1);
  while(rd!=wr) @(negedge clk);
  // All legacy formats share this transparent registered path.
  for(n=0;n<30;n=n+1) send(n*19,0);
  while(rd!=wr) @(negedge clk);
  // Reset must cancel a half-completed transaction, with no ghost valid.
  send(128,1); @(negedge clk);m_ready=0;
  @(negedge clk);rst_n=0;
  repeat(2) @(negedge clk);rst_n=1;m_ready=1;
  send(64,1);while(rd!=wr) @(negedge clk);
  repeat(3) @(negedge clk);
  if(m_valid) $fatal(1,"ghost valid");
  if(first_emit-first_accept != PIPE+1) $fatal(1,"registered latency mismatch: %0d",first_emit-first_accept);
  $display("PASS exhaustive INT8, half ordering, stalls, legacy passthrough, reset; accepted=%0d cycles=%0d",accepted,cycle);
  $finish;
 end
 // Deterministic irregular backpressure independent of source data.
 always @(negedge clk) if(rst_n && cycle>=12 && cycle<380) m_ready=(cycle%7!=2 && cycle%7!=3);
 initial begin #100000; $fatal(1,"deadlock watchdog");end
endmodule
